const QA_MODE=new URLSearchParams(location.search).get('qa')==='1',KEY=QA_MODE?'teyvat-embers-qa-v1':'teyvat-embers-v1',PREF=QA_MODE?'teyvat-embers-qa-settings':'teyvat-embers-settings';let state=createGame(Date.now()),saved=null,prefs={volume:.5,music:.8,sfx:1,fast:false,shake:true,glow:.85,audioVersion:2},modal=null,statusHero='lohen',selectedEnemy=null,lastEvents=[],drag=null,toastTimer,cutinTimer,busy=false,titleEntered=false,skillSelection=null,selectedCard=null;
try{saved=hydrate(localStorage.getItem(KEY));}catch{}try{const previous=JSON.parse(localStorage.getItem(PREF)||'{}');prefs={...prefs,...previous};if(!previous.audioVersion&&previous.volume!==undefined)prefs.volume=Math.sqrt(Math.max(0,Math.min(1,previous.volume)));prefs.audioVersion=2;}catch{}
