function keywordStripHTML(info){
 if(!info||info.blind)return '';
 const hay=(info.desc||'')+' '+(info.name||'');
 const found=KEYWORD_GLOSSARY.filter(([k])=>hay.includes(k)).slice(0,4),n=info.numbers;
 const real=n?.damage!=null?`<span class="keyword-chip numbers-chip"><strong>실제 수치</strong>피해 ${n.damage} · 치명 ${Math.round(n.crit*100)}% 시 ${n.critDamage}</span>`:n?.shield!=null?`<span class="keyword-chip numbers-chip"><strong>실제 수치</strong>보호막 ${n.shield}${n.party?' (파티 전원 각각)':''}</span>`:'';
 if(!found.length&&!real)return '';
 return `<div class="keyword-strip" role="note">${real}${found.map(([k,v])=>`<span class="keyword-chip"><strong>${k}</strong>${v}</span>`).join('')}</div>`;
}
function clearEnemyPreviews(){$$('.enemy-preview-badge').forEach(el=>el.remove());}
function updateEnemyPreviews(uid,hoverEnemyId=null){
 clearEnemyPreviews();
 if(!uid||state.phase!=='battle')return;
 const pred=predictCardEffect(state,uid,hoverEnemyId);
 if(!pred||pred.type!=='attack')return;
 for(const [eid,info] of Object.entries(pred.enemies)){
  const node=$(`[data-enemy="${eid}"]`);if(!node)continue;
  const tag=info.willKill?' · 처치':info.willEcho?' · 잔향 노출':info.wardBroken?' · 장막 파괴':'';
  const cls=info.willKill?'is-kill':info.willEcho?'is-echo':info.wardBroken?'is-break':'';
  node.insertAdjacentHTML('beforeend',`<span class="enemy-preview-badge ${cls}">-${info.damage}${tag}</span>`);
 }
}
function drawThreats(focus=null){const svg=$('.threat-lines'),field=$('.battle-field');if(!svg||!field)return;const fr=field.getBoundingClientRect(),sc=fr.width/field.clientWidth;svg.setAttribute('viewBox',`0 0 ${field.clientWidth} ${field.clientHeight}`);svg.innerHTML='<defs><marker id="target-arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 7 4 0 8" fill="none" stroke="currentColor" stroke-width="1.3"/></marker></defs>'+state.battle.enemies.filter(e=>e.hp>0&&!e.intent.stunned&&(e.intent.damage||e.intent.stress)&&e.intent.target).map(e=>{const from=$(`[data-enemy="${e.id}"] .intent`),to=$(`[data-ally="${e.intent.target}"] .sprite`);if(!from||!to)return '';const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),x=(a.left+a.width*.5-fr.left)/sc,y=(a.bottom-fr.top)/sc,tx=(b.left+b.width*Number(to.dataset.anchorX||.5)-fr.left)/sc,ty=(b.top+b.height*.5-fr.top)/sc;return `<path class="threat-path ${focus===e.id?'focused':''}" data-threat="${e.id}" d="M${x} ${y} Q${(x+tx)/2} ${Math.min(y,ty)-45} ${tx} ${ty}" marker-end="url(#target-arrow)"/>`;}).join('');svg.classList.toggle('hidden-lines',!threatsVisible);}
const recruitCopy={durin:['전장을 한꺼번에 뒤흔들 힘','높은 비용의 광역 공격. 알베도가 보호막과 행동력을 지원합니다.'],illuga:['흔들리는 전선을 지탱할 빛','보호막과 엄호로 동료를 지킵니다. 플린스가 단일 공격과 강화를 지원합니다.'],jahoda:['막힌 길에 여유를 만들 손길','손패와 행동력을 정리하고 보급품을 더 찾아옵니다. 네페르가 적을 약화합니다.']};
