function refinePage(){return `<section class="refinement-scene"><div class="eyebrow">A MEMORY TO KEEP</div><h2>남길 전투의 기억</h2><p>현재 편성의 카드 중 제시된 카드 하나를 무료로 각성합니다.</p><div class="card-gallery refinement-candidates">${offerCards()}</div>${button('각성하지 않고 진행','skip-upgrade','','flat')}</section>`;}
let cardRewardPick=null,cardRewardId=null;
function cardRewardPage(){const o=state.cardOffer;if(o?.id!==cardRewardId){cardRewardId=o?.id;cardRewardPick=null;}const picked=o?.candidates.find(c=>`${c.owner}:${c.key}`===cardRewardPick);return `<section class="refinement-scene card-reward-scene"><div class="eyebrow">${o?.source==='event'?'A NEW TACTIC':'SPOILS OF BATTLE'}</div><h2>덱에 더할 카드</h2><p>한 장을 골라 그 전투원의 덱에 넣습니다. 덱을 가볍게 유지하려면 넘겨도 됩니다.</p><div class="card-gallery refinement-candidates">${(o?.candidates||[]).map(c=>{const id=`${c.owner}:${c.key}`;return `<div class="card-choice ${cardRewardPick===id?'selected':cardRewardPick?'muted':''}" style="--owner:${HEROES[c.owner].color}"><small class="card-choice-owner">${HEROES[c.owner].name}</small>${catalogCard(c.owner,c.key,{viewState:previewState(c.owner,c.key),action:'card-pick',extra:`data-hero="${c.owner}" data-card-key="${c.key}" aria-pressed="${cardRewardPick===id}"`,label:'덱에 추가'})}</div>`;}).join('')}</div><div class="card-reward-actions">${picked?button(`${esc(CARDS[picked.key].name)} 추가`,'card-confirm',`data-hero="${picked.owner}" data-card-key="${picked.key}"`,'primary'):''}${button('카드를 더하지 않고 진행','card-skip','','flat')}</div></section>`;}
function eventRemovePage(){return `<section class="refinement-scene event-removal"><div class="eyebrow">A MEMORY TO LEAVE</div><h2>내려놓을 카드 한 장</h2><p>전투원마다 최소 세 장은 남겨야 합니다.</p>${state.party.map(id=>`<section class="removal-owner-group" style="--group-color:${HEROES[id].color}"><h3>${HEROES[id].name}</h3><div class="card-gallery">${ownedDeck(state,id).map(c=>`<div class="card-choice">${cardHTML(c,0,1,{catalog:true,viewState:previewState(id,c.key),action:'event-remove-card',extra:`data-hero="${id}" data-uid="${c.uid}"`,label:'한 장 제거'})}</div>`).join('')}</div></section>`).join('')}${button('제거하지 않고 진행','event-remove-skip','','flat')}</section>`;}
function recruit(){const lines=recruitScript(state.party.length),step=Math.min(state.recruitLine||0,lines.length),options=Object.keys(HEROES).filter(id=>!state.party.includes(id)),controls=button('다음 대화','recruit-next','','primary')+button('대화 건너뛰기','recruit-skip','','small');if(step<lines.length)return dialogueStage({hero:'lohen',speaker:lines[step][0],text:lines[step][1],controls,counter:`${step+1} / ${lines.length}`});return `<section class="recruit-with-cutin"><div class="recruit-cutin-wrap"><img src="${NEW_ART}scenes/tutorial-${state.party.length===1?1:2}.webp" alt="튜토리얼 컷신 ${state.party.length===1?1:2}"><p>서풍 매가 다음 응답을 기다린다.</p></div><div class="falcon-choices">${options.map(id=>button(`<strong>${recruitCopy[id][0]}</strong><span>${HEROES[id].summary}</span><small>${HEROES[id].role}</small>`,'recruit',`data-hero="${id}" style="--choice-border:${HEROES[id].color}" aria-label="${HEROES[id].name} 영입"`,'falcon-choice')).join('')}</div></section>`;}
function eventPage(){const offer=state.eventOffer,identity=offer?`${state.node}:${offer.id}`:`legacy:${state.node}`;if(eventSelectionId!==identity){eventSelection=null;eventSelectionId=identity;}const legacy=[{id:'risk',label:'균열 너머로 손을 뻗는다',benefit:{kind:'legacy'},cost:{stress:12}},{id:'safe',label:'안전한 길로 돌아간다',benefit:{kind:'gold',amount:8},cost:{}}],choices=offer?.choices||legacy;return `<section class="event-battle"><div class="event-field"><div class="allies">${state.party.map(heroFighter).join('')}</div><article class="event-narrative"><small>ENCOUNTER</small><h2>${esc(offer?.name||'뒤집힌 성상')}</h2><p>${esc(offer?.text||'균열 너머, 버려진 보급품이 손에 닿을 듯 떠 있다.')}</p></article></div><div class="event-decision-row ${eventSelection?'has-selection':''}">${choices.map(c=>`<div class="event-choice-wrap ${eventSelection===c.id?'selected':eventSelection?'muted':''}">${button(`<strong>${esc(c.label)}</strong>${c.dice?`<span class="event-dice-line">d20 ${c.dice.dc} 이상 · ${benefitText(c.benefit)}</span><small>실패 시 ${costText({...c.cost,...c.fail})}</small>`:c.mystery?'<span class="event-mystery-line">무엇이 돌아올지 알 수 없다</span><small>대가도 알 수 없다</small>':`<span>${c.benefit.kind==='legacy'?'d20 판정 · 위험한 보급품':benefitText(c.benefit)}</span><small>${Object.keys(c.cost).length?costText(c.cost):'추가 대가 없음'}</small>`}${eventSelection===c.id?'<em>다시 눌러 확정</em>':''}`,'event-select',`data-choice="${c.id}" aria-pressed="${eventSelection===c.id}"`,'event-decision')}${button(icon('search'),'event-details',`data-choice="${c.id}" aria-label="${esc(c.label)} 획득품 정보"`,'event-info')}</div>`).join('')}</div></section>`;}
function selectEventChoice(id){if(eventSelection!==id){eventSelection=id;$('#screen').innerHTML=eventPage();requestAnimationFrame(()=>sortSceneDepth());return;}if(state.eventOffer){const dice=state.eventOffer.choices.find(c=>c.id===id)?.dice;if(run({type:'event',choice:id})&&dice)diceResult();}else if(id==='risk'){if(run({type:'event',choice:'risk'}))diceResult();}else run({type:'event',choice:'safe'});}
function eventDetails(id){const c=state.eventOffer?.choices.find(c=>c.id===id);if(!c){modalOpen('사건 정보',id==='safe'?'<p>안전한 길에서 모라 8을 얻고, 각자의 정신 부담을 5 낮춥니다.</p>':'<p>위험한 선택은 주사위 판정으로 성공 여부를 결정합니다. 실패 시 정신 부담과 신체 손상을 얻을 수 있습니다.</p>','event-details');return;}if(c.dice||c.mystery){modalOpen('사건 정보',`<div class="event-detail-content"><h2>${esc(c.label)}</h2>${c.dice?`<p>20면 주사위를 굴려 ${c.dice.dc} 이상이면 성공합니다.${state.party.includes('jahoda')?' 야호다가 있으면 +2 보정을 받습니다.':''}${c.dice.hero&&c.dice.hero!=='jahoda'&&state.party.includes(c.dice.hero)?' 이 판정은 '+HEROES[c.dice.hero].name+'에게 유리합니다.':''}</p><div class="event-cost-detail"><h3>성공</h3><p>${benefitText(c.benefit)}</p><h3>실패</h3><p>${costText({...c.cost,...c.fail})}</p></div>`:'<p>손을 뻗기 전에는 결과를 알 수 없습니다. 좋은 일일 수도, 무거운 대가일 수도 있습니다.</p>'}<small>이 창을 닫아도 선택은 확정되지 않습니다.</small></div>`,'event-details');return;}const b=c.benefit,items=b.kind==='equipment'?(b.item?[b.item]:Object.keys(EQUIPMENT).filter(k=>(EQUIPMENT[k].rarity==='elite')===!!b.elite)):[];modalOpen('획득품 정보',`<div class="event-detail-content"><h2>${esc(c.label)}</h2><p>${benefitText(b)}</p>${items.map(equipmentCard).join('')}${b.kind==='upgrade'?'<p>편성 중인 전투원의 무작위 카드 세 장 중 하나에 전술 각성을 적용합니다. 카드마다 네 방향이 있으며, 잔불 각성이 추가될 수 있습니다.</p>':''}${b.kind==='remove'?'<p>보유 카드 한 장을 골라 제거합니다. 전투원마다 최소 세 장은 남겨야 합니다.</p>':''}<div class="event-cost-detail"><h3>${Object.keys(c.cost).length?'선택의 대가':'추가 대가 없음'}</h3><p>${costText(c.cost)}</p>${c.cost.curse?`<div class="card-gallery event-curse-preview">${catalogCard(state.party[0],'curse_echo')}</div><p>악몽의 잔향이 무작위 전투원의 덱에 추가됩니다.</p>`:''}</div><small>이 창을 닫아도 선택은 확정되지 않습니다.</small></div>`,'event-details');}

function camp(){return base(true);}
function benefitText(b){return ({gold:`모라 +${b.amount||0}`,upgrade:'랜덤한 세 카드 중 하나 연마',remove:'카드 한 장 제거',equipment:b.elite?'엘리트급 장비 획득':'장비 획득',heal:`공용 체력 +${b.amount||0}% (${Math.round((b.amount||0)*state.maxHp/100)})`,calm:`전원 정신 부담 -${b.amount||0}`,support:`지원 게이지 +${b.amount||0}`,card:'카드 세 장 중 한 장 획득',none:'얻은 것 없음'})[b?.kind]||'';}
function costText(c={}){const parts=[];if(c.hp)parts.push(`공용 체력 -${c.hp}% (${Math.round(c.hp*state.maxHp/100)})`);if(c.gold)parts.push('모라 -'+c.gold);if(c.stress)parts.push('각자 정신 부담 +'+c.stress);if(c.curse)parts.push('디버프 카드 +'+c.curse);if(c.injury)parts.push('무작위 동료 부상 '+c.injury);return parts.join(' · ')||'추가 대가 없음';}
function aftermathStage(content,kind){return `<section class="battle aftermath-stage ${kind}-stage"><div class="battle-field"><div class="allies">${state.party.map(heroFighter).join('')}</div><div class="enemies" aria-hidden="true"></div></div>${content}</section>`;}
function reward(){const r=state.lastReward,pending=r?.pending,e=state.eventResult;return aftermathStage(`<aside class="field-loot"><h2>${e?'선택의 흔적':'전투의 전리품'}</h2>${pending?`<div class="loot-line">${icon('coin')}<span>모라</span><strong>+${r.gold}</strong></div><div class="loot-line">${icon('fire')}<span>전투 경험</span><strong>+${r.xp}</strong></div>${(r.equipment||[]).map(key=>`<div class="field-gear">${equipmentCard(key)}</div>`).join('')}${r.upgradeOffer?`<div class="loot-line">${icon('cards')}<span>전술 각성</span><strong>1회</strong></div>`:''}`:e?.benefit?`<p>${esc(e.choice)}</p>${e.die?`<p class="event-roll ${e.success?'success':'fail'}">판정 ${e.total} / 목표 ${e.dc} · ${e.success?'성공':'실패'}</p>`:''}${e.revealed?'<p class="event-roll">결과가 드러났습니다.</p>':''}<div class="loot-line">${icon('shop')}<span>${benefitText(e.benefit)}${e.item?' · '+EQUIPMENT[e.item].name:''}</span></div><small>${costText(e.cost)}</small>${e.fallback?`<p>${e.fallback}</p>`:''}`:'<p>남은 흔적을 정리했습니다.</p>'}</aside><div class="field-reward-actions">${button(pending?'전리품 수령':'다음 지점 선택','reward-claim','','primary')}${pending?button('넘어가기','reward-skip','','flat'):''}</div>`,'reward');}

