 const tile=(ic,name,sub,action,cls='',attrs='')=>button(`<span class="tile-icon">${icon(ic)}</span><span class="tile-text"><strong>${name}</strong><small>${sub}</small></span>`,action,attrs,`lobby-tile ${cls}`);
